<template><div class="dash-stack"><div class="dash-toolbar"><div><h2>My documents</h2><p>Private files stored in your account. Select documents explicitly when attaching them to a chat.</p></div><div><input ref="picker" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.txt,.csv" hidden @change="choose"/><IconButton icon="upload" label="Upload documents" @click="picker?.click()" :loading="uploading"/></div></div><div class="glass-panel document-drop" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop" :class="{dragging}"><div v-if="dragging" class="drop-hint">Drop files to upload</div><div class="table-tools"><div class="search-box"><span>⌕</span><input v-model="q" placeholder="Search documents" @input="load(1)"/></div><span class="muted">{{result.totalCount||0}} documents</span></div><div v-if="errors.length" class="inline-alert">{{errors.join(' · ')}}</div><div v-if="loading" class="state-message">Loading documents…</div><div v-else-if="!result.items?.length" class="state-message">No documents uploaded yet. Use the upload icon or drag files here.</div><div v-else class="document-grid"><article v-for="doc in result.items" :key="doc.id" class="document-card"><div class="document-icon">{{fileIcon(doc.contentType)}}</div><div class="document-copy"><b>{{doc.fileName}}</b><small>{{formatSize(doc.sizeBytes)}} · {{new Date(doc.createdAt).toLocaleDateString()}}</small></div><div class="document-actions"><IconButton icon="view" label="View document" @click="view(doc)"/><IconButton icon="delete" label="Delete document" variant="danger" @click="remove(doc)"/></div></article></div><div v-if="uploadStates.length" class="upload-queue"><div v-for="item in uploadStates" :key="item.id" class="upload-queue-row"><span>{{item.name}}</span><div class="upload-progress"><i :style="{width:item.progress+'%'}"/></div><small :class="item.status">{{item.status==='error'?item.error:item.status==='done'?'Uploaded':item.progress+'%'}}</small></div></div><div class="pagination"><span>Page {{result.page||1}} of {{result.totalPages||0}}</span><div><IconButton icon="previous" label="Previous page" :disabled="!result.hasPrevious" @click="load((result.page||1)-1)"/><IconButton icon="next" label="Next page" :disabled="!result.hasNext" @click="load((result.page||1)+1)"/></div></div></div><ConfirmDialog :open="!!pendingDelete" title="Delete document" :message="`Delete ${pendingDelete?.fileName}? This cannot be undone.`" confirm-label="Delete document" danger @cancel="pendingDelete=null" @confirm="confirmRemove"/></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{platformApi}from'@/services/platform';import IconButton from'@/components/ui/IconButton.vue';import ConfirmDialog from'@/components/ui/ConfirmDialog.vue';const result=ref<any>({items:[]}),picker=ref<HTMLInputElement|null>(null),q=ref(''),loading=ref(false),uploading=ref(false),uploadCount=ref(0),dragging=ref(false),errors=ref<string[]>([]),uploadStates=ref<any[]>([]),pendingDelete=ref<any>(null);async function load(page=1){loading.value=true;try{result.value=(await platformApi.documents(page,q.value)).data}finally{loading.value=false}}async function upload(files:File[]){errors.value=[];uploading.value=true;uploadCount.value=files.length;for(const file of files){const item:any={id:crypto.randomUUID(),name:file.name,progress:0,status:'uploading',error:''};uploadStates.value.unshift(item);try{await platformApi.uploadDocument(file,(event:any)=>{if(event.total)item.progress=Math.round(event.loaded*100/event.total)});item.progress=100;item.status='done'}catch(e:any){item.status='error';item.error=e.response?.data?.detail||'Upload failed';errors.value.push(`${file.name}: ${item.error}`)}}uploading.value=false;uploadCount.value=0;await load(result.value.page||1)}function choose(e:Event){const el=e.target as HTMLInputElement;if(el.files?.length)upload(Array.from(el.files));el.value=''}function drop(e:DragEvent){dragging.value=false;if(e.dataTransfer?.files.length)upload(Array.from(e.dataTransfer.files))}async function view(doc:any){try{const {data}=await platformApi.documentUrl(doc.id);window.open(data.url,'_blank','noopener')}catch(e:any){errors.value=[e.response?.data?.detail||'Could not open document']}}function remove(doc:any){pendingDelete.value=doc}async function confirmRemove(){if(!pendingDelete.value)return;try{await platformApi.deleteDocument(pendingDelete.value.id);pendingDelete.value=null;await load(result.value.page||1)}catch(e:any){errors.value=[e.response?.data?.detail||'Could not delete document']}}function fileIcon(type:string){return type==='application/pdf'?'PDF':type.startsWith('image/')?'IMG':type==='text/csv'?'CSV':'TXT'}function formatSize(n:number){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`}onMounted(()=>load());</script>
